FuncDef.Code:
// Based on: "Generalized Distance Functions" by Akleman and Chen.
// From: http://mercury.sexy/hg_sdf/
// License: MIT
//
// Code by luk77 based on: 
// https://en.wikipedia.org/wiki/Rhombic_dodecahedron
// https://en.wikipedia.org/wiki/Cuboctahedron
// (Cuboctahedron vertices are used as normals for "cutting planes" in Rhombic dodecahedron - 
// - Cuboctahedron and Rhombic dodecahedron are dual polyhedrons)
float hgsdfRhombicDodecahedronHard(vec3 p, float r)
{
    const vec3 v0 = normalize(vec3( 1,    1,    0));
    const vec3 v1 = normalize(vec3( 1,   -1,    0));
    const vec3 v2 = normalize(vec3(-1,    1,    0));
    const vec3 v3 = normalize(vec3(-1,   -1,    0));
    const vec3 v4 = normalize(vec3( 1,    0,    1));
    const vec3 v5 = normalize(vec3( 1,    0,   -1));
    const vec3 v6 = normalize(vec3(-1,    0,    1));
    const vec3 v7 = normalize(vec3(-1,    0,   -1));
    const vec3 v8 = normalize(vec3( 0,    1,    1));
    const vec3 v9 = normalize(vec3( 0,    1,   -1));
    const vec3 v10= normalize(vec3( 0,   -1,    1));
    const vec3 v11= normalize(vec3( 0,   -1,   -1));

    float d = 0.0;
    d = max(d, abs(dot(p, v0 )));
    d = max(d, abs(dot(p, v1 )));
    d = max(d, abs(dot(p, v2 )));
    d = max(d, abs(dot(p, v3 )));
    d = max(d, abs(dot(p, v4 )));
    d = max(d, abs(dot(p, v5 )));
    d = max(d, abs(dot(p, v6 )));
    d = max(d, abs(dot(p, v7 )));
    d = max(d, abs(dot(p, v8 )));
    d = max(d, abs(dot(p, v9 )));
    d = max(d, abs(dot(p, v10)));
    d = max(d, abs(dot(p, v11)));

    return d - r;
}
